import { z } from 'zod/v3';
import {
  CONTEXT_ASSET_MAX_ITEMS,
  contextAssetInputSchema,
  runLabelSchema,
  VARIANT_COUNT_MAX,
  VARIANT_COUNT_MIN,
} from '../agent-variants/contracts';
import { referencePicksSchema } from '../routes/variantRequestSchema';
const DIRECTION_TITLE_MAX_WORDS = 5;
const DIRECTION_SUBTITLE_MAX_WORDS = 10;
const RELEVANT_FILE_MAX_COUNT = 12;
export const explorationShape = {
  instruction: z.string().trim().min(1).describe('What to explore or change'),
  runLabel: runLabelSchema
    .unwrap()
    .describe(
      'start: AI-authored 1–3 word summary shared by every direction in this batch',
    ),
  briefs: z
    .array(
      z
        .object({
          label: z
            .string()
            .trim()
            .min(1)
            .max(48)
            .refine(
              (label) => label.split(/\s+/).length <= DIRECTION_TITLE_MAX_WORDS,
              {
                message: 'Direction titles must contain at most 5 words',
              },
            )
            .describe('AI-authored 1–5 word direction title'),
          body: z
            .string()
            .trim()
            .min(1)
            .max(600)
            .refine(
              (body) =>
                body.split(/\s+/).length <= DIRECTION_SUBTITLE_MAX_WORDS,
              {
                message: 'Direction subtitles must contain at most 10 words',
              },
            )
            .describe('Concise direction subtitle of at most 10 words'),
          notes: z
            .string()
            .trim()
            .min(1)
            .max(4000)
            .optional()
            .describe(
              'Optional implementation notes for this direction, passed verbatim to its worker (design tokens, motion specs, constraints). Not shown in UI chips.',
            ),
          visualReferenceUrl: z.string().url().optional(),
        })
        .strict(),
    )
    .min(VARIANT_COUNT_MIN)
    .max(VARIANT_COUNT_MAX)
    .superRefine((briefs, context) => {
      const labels = briefs.map((brief) => brief.label.toLowerCase());
      if (new Set(labels).size !== labels.length) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          message: 'Direction titles must be distinct',
        });
      }
    })
    .describe(
      'One AI-authored title/subtitle brief per direction; use one for a single visualization or distinct briefs for divergent ideas; briefs.length sets the variant count',
    ),
  element: z
    .string()
    .optional()
    .describe('start: CSS selector scoping the variation'),
  files: z
    .array(z.string().trim().min(1))
    .max(RELEVANT_FILE_MAX_COUNT)
    .optional()
    .describe(
      'start: known project files for workers to inspect before broader discovery',
    ),
  fresh: z
    .boolean()
    .optional()
    .describe(
      'start: create isolated prototypes under the project workspace in .rivet/<slug>/; does not implement them in application source. Use an empty project directory for a separate workspace.',
    ),
  profile: z
    .enum(['auto', 'off'])
    .optional()
    .describe(
      'start: saved references are off by default; auto selects relevant references when the user asks for them',
    ),
  guidance: z
    .enum(['auto', 'off'])
    .optional()
    .describe(
      'start: apply saved instructions, or turn them off for this request only',
    ),
  excludedGuidanceIds: z
    .array(z.string().min(1).max(200))
    .optional()
    .describe(
      'start: saved instruction document IDs to exclude for this request only',
    ),
  fidelity: z
    .enum(['low', 'medium', 'high'])
    .optional()
    .describe(
      "start: the user's design-fidelity intent. low = fast sketch-grade workers (quick ideas/explorations); medium = balanced; high = the default with maximum deliberation, up to a few minutes (polished/pixel-perfect/final asks). Omit when unstated.",
    ),
  workerProvider: z
    .enum(['claude', 'codex', 'cursor'])
    .optional()
    .describe(
      'start: run the workers on this provider CLI instead of the one matching your caller agent. Pass ONLY when the user explicitly asks ("use opus for the workers") — it spends on that provider\'s subscription, so never infer it.',
    ),
  workerModel: z
    .string()
    .trim()
    .min(1)
    .max(200)
    .optional()
    .describe(
      'start: pin the worker model id for the selected (or caller-matching) provider. Pass ONLY on an explicit user request; a pinned model never silently falls back.',
    ),
  contextImages: z
    .array(z.string().trim().min(1))
    .min(1)
    .optional()
    .describe(
      'start: local reference image file paths (png/jpg/webp/gif/avif). Rivet copies them into the run context and every worker views them natively — pass the actual images instead of describing them in notes.',
    ),
  contextAssets: z
    .array(contextAssetInputSchema)
    .min(1)
    .max(CONTEXT_ASSET_MAX_ITEMS)
    .optional()
    .describe(
      'start: local regular files copied into every variant workspace and exposed to workers with stable file and reference paths.',
    ),
  referencePages: z
    .array(z.string().trim().min(1))
    .min(1)
    .max(3)
    .optional()
    .describe(
      'Reference page URLs. Rivet renders each page server-side (design evidence + screenshot) — pass the raw URLs, never capture evidence or screenshot pages yourself.',
    ),
  referenceVideos: z
    .array(z.string().trim().min(1))
    .min(1)
    .max(2)
    .optional()
    .describe(
      'Local reference video file paths (mp4/mov/webm/m4v). Rivet samples keyframes server-side — pass the raw paths, never run ffmpeg yourself.',
    ),
  referencePicks: referencePicksSchema
    .optional()
    .describe(
      'start: up to 3 saved library references you chose, as {profileId, picks: [{key, reason}]} with keys from rivet_find_references. Rivet attaches them as removable reference chips and receipts without running its own selection. profile: "off" drops them.',
    ),
  baseDirectionId: z
    .string()
    .optional()
    .describe(
      'start: direction ref (e.g. warm-editorial-green), sessionId:variantId, or projectId/sessionId:variantId — create a new direction from the selected variant. A saved variant may be adopted into the current session; use returned session and variant IDs for follow-up calls.',
    ),
  project: z.string().trim().min(1).describe('Absolute project root path'),
};
